  1	import { useCallback, useEffect, useMemo, useRef } from "react";
  2	import { TLShapeId, useEditor, useValue } from "tldraw";
  3	import DiscourseGraphPlugin from "~/index";
  4	import { DiscourseRelationShape } from "~/components/canvas/shapes/DiscourseRelationShape";
  5	import {
  6	  getArrowBindings,
  7	  getArrowInfo,
  8	} from "~/components/canvas/utils/relationUtils";
  9	import {
 10	  getDiscourseNodeTypeId,
 11	  getValidRelationTypesForNodePair,
 12	} from "~/components/canvas/utils/relationTypeUtils";
 13	
 14	type RelationTypeDropdownProps = {
 15	  arrowId: TLShapeId;
 16	  plugin: DiscourseGraphPlugin;
 17	  onSelect: (relationTypeId: string) => void;
 18	  onDismiss: () => void;
 19	};
 20	
 21	export const RelationTypeDropdown = ({
 22	  arrowId,
 23	  plugin,
 24	  onSelect,
 25	  onDismiss,
 26	}: RelationTypeDropdownProps) => {
 27	  const editor = useEditor();
 28	  const dropdownRef = useRef<HTMLDivElement>(null);
 29	
 30	  const arrow = useValue<DiscourseRelationShape | null>(
 31	    "dropdownArrow",
 32	    () => editor.getShape<DiscourseRelationShape>(arrowId) ?? null,
 33	    [editor, arrowId],
 34	  );
 35	
 36	  // Auto-dismiss if arrow is deleted
 37	  useEffect(() => {
 38	    if (!arrow) {
 39	      onDismiss();
 40	    }
 41	  }, [arrow, onDismiss]);
 42	
 43	  // Get valid relation types based on source/target node types
 44	  const validRelationTypes = useMemo(() => {
 45	    if (!arrow) return [];
 46	
 47	    const bindings = getArrowBindings(editor, arrow);
 48	    if (!bindings.start || !bindings.end) return [];
 49	
 50	    const startNode = editor.getShape(bindings.start.toId);
 51	    const endNode = editor.getShape(bindings.end.toId);
 52	
 53	    if (!startNode || !endNode) return [];
 54	
 55	    const startNodeTypeId = getDiscourseNodeTypeId(startNode);
 56	    const endNodeTypeId = getDiscourseNodeTypeId(endNode);
 57	
 58	    if (!startNodeTypeId || !endNodeTypeId) return [];
 59	
 60	    return getValidRelationTypesForNodePair({
 61	      settings: plugin.settings,
 62	      sourceNodeTypeId: startNodeTypeId,
 63	      targetNodeTypeId: endNodeTypeId,
 64	    });
 65	  }, [arrow, editor, plugin]);
 66	
 67	  // Position dropdown at arrow midpoint
 68	  const dropdownPosition = useValue<{ left: number; top: number } | null>(
 69	    "dropdownPosition",
 70	    () => {
 71	      if (!arrow) return null;
 72	
 73	      const info = getArrowInfo(editor, arrow);
 74	      if (!info) return null;
 75	
 76	      // Get the midpoint in page space
 77	      const pageTransform = editor.getShapePageTransform(arrow.id);
 78	      const midInPage = pageTransform.applyToPoint(info.middle);
 79	
 80	      const vp = editor.pageToViewport(midInPage);
 81	      return { left: vp.x, top: vp.y };
 82	    },
 83	    [editor, arrow?.id],
 84	  );
 85	
 86	  // Handle click outside
 87	  useEffect(() => {
 88	    const handlePointerDown = (e: PointerEvent) => {
 89	      if (
 90	        dropdownRef.current &&
 91	        !dropdownRef.current.contains(e.target as Node)
 92	      ) {
 93	        onDismiss();
 94	      }
 95	    };
 96	
 97	    // Delay to avoid immediately triggering from the pointer up that opened this
 98	    const timer = setTimeout(() => {
 99	      window.addEventListener("pointerdown", handlePointerDown, true);
100	    }, 100);
101	
102	    return () => {
103	      clearTimeout(timer);
104	      window.removeEventListener("pointerdown", handlePointerDown, true);
105	    };
106	  }, [onDismiss]);
107	
108	  // Handle Escape key
109	  useEffect(() => {
110	    const handleKeyDown = (e: KeyboardEvent) => {
111	      if (e.key === "Escape") {
112	        onDismiss();
113	      }
114	    };
115	    window.addEventListener("keydown", handleKeyDown, true);
116	    return () => window.removeEventListener("keydown", handleKeyDown, true);
117	  }, [onDismiss]);
118	
119	  const handleSelect = useCallback(
120	    (relationTypeId: string) => {
121	      onSelect(relationTypeId);
122	    },
123	    [onSelect],
124	  );
125	
126	  if (!dropdownPosition || !arrow) return null;
127	
128	  return (
129	    <div
130	      ref={dropdownRef}
131	      className="pointer-events-auto absolute z-30 -translate-x-1/2 -translate-y-1/2"
132	      style={{
133	        left: `${dropdownPosition.left}px`,
134	        top: `${dropdownPosition.top}px`,
135	      }}
136	      onPointerDown={(e) => e.stopPropagation()}
137	      onPointerUp={(e) => e.stopPropagation()}
138	      onClick={(e) => e.stopPropagation()}
139	    >
140	      <div className="max-h-60 min-w-40 overflow-y-auto rounded-lg border bg-white p-1 shadow-lg">
141	        <div className="px-2 py-1 text-xs font-medium uppercase tracking-wide text-gray-500">
142	          Relation Type
143	        </div>
144	        {validRelationTypes.map((rt) => (
145	          <button
146	            key={rt.id}
147	            onClick={() => handleSelect(rt.id)}
148	            className="flex w-full cursor-pointer items-center gap-2 rounded border-none bg-transparent px-2 py-1.5 text-left text-sm text-gray-700 hover:bg-gray-100"
149	          >
150	            <span
151	              className="h-2 w-2 shrink-0 rounded-full"
152	              style={{ backgroundColor: rt.color }}
153	            />
154	            {rt.label}
155	          </button>
156	        ))}
157	      </div>
158	    </div>
159	  );
160	};
