    39	type RelationTypeSettings = {
    40	  discourseRelations: DiscourseRelation[];
    41	  relationTypes: DiscourseRelationType[];
    42	};
    43	
    44	/**
    45	 * Checks the direction of a discourse relation between two node types.
    46	 * Returns whether the relation exists in the direct (source→target)
    47	 * and/or reverse (target→source) direction.
    48	 */
    49	export const getRelationDirection = ({
    50	  discourseRelations,
    51	  relationTypeId,
    52	  sourceNodeTypeId,
    53	  targetNodeTypeId,
    54	}: {
    55	  discourseRelations: DiscourseRelation[];
    56	  relationTypeId: string;
    57	  sourceNodeTypeId: string;
    58	  targetNodeTypeId: string;
    59	}): { direct: boolean; reverse: boolean } => {
    60	  let direct = false;
    61	  let reverse = false;
    62	
    63	  for (const relation of discourseRelations) {
    64	    if (relation.relationshipTypeId !== relationTypeId) continue;
    65	    if (
    66	      relation.sourceId === sourceNodeTypeId &&
    67	      relation.destinationId === targetNodeTypeId
    68	    ) {
    69	      direct = true;
    70	    }
    71	    if (
    72	      relation.sourceId === targetNodeTypeId &&
    73	      relation.destinationId === sourceNodeTypeId
    74	    ) {
    75	      reverse = true;
    76	    }
    77	    if (direct && reverse) break;
    78	  }
    79	
    80	  return { direct, reverse };
    81	};
    82	
    83	export const getRelationLabelForDirection = ({
    84	  discourseRelations,
    85	  relationType,
    86	  sourceNodeTypeId,
    87	  targetNodeTypeId,
    88	}: {
    89	  discourseRelations: DiscourseRelation[];
    90	  relationType: DiscourseRelationType;
    91	  sourceNodeTypeId: string;
    92	  targetNodeTypeId: string;
    93	}): string => {
    94	  const { direct, reverse } = getRelationDirection({
    95	    discourseRelations,
    96	    relationTypeId: relationType.id,
    97	    sourceNodeTypeId,
    98	    targetNodeTypeId,
    99	  });
   100	
   101	  if (reverse && !direct) {
   102	    return relationType.complement;
   103	  }
   104	
   105	  return relationType.label;
   106	};
   107	
   108	/**
   109	 * Returns the list of valid relation types for a given pair of node types,
   110	 * checking both directions of the discourse relations.
   111	 */
   112	export const getValidRelationTypesForNodePair = ({
   113	  settings,
   114	  sourceNodeTypeId,
   115	  targetNodeTypeId,
   116	}: {
   117	  settings: RelationTypeSettings;
   118	  sourceNodeTypeId: string;
   119	  targetNodeTypeId: string;
   120	}): { id: string; label: string; color: string }[] => {
   121	  const validTypes: { id: string; label: string; color: string }[] = [];
   122	
   123	  for (const relationType of settings.relationTypes) {
   124	    const { direct, reverse } = getRelationDirection({
   125	      discourseRelations: settings.discourseRelations,
   126	      relationTypeId: relationType.id,
   127	      sourceNodeTypeId,
   128	      targetNodeTypeId,
   129	    });
   130	
   131	    if (direct || reverse) {
   132	      validTypes.push({
   133	        id: relationType.id,
   134	        label: relationType.label,
   135	        color: COLOR_PALETTE[relationType.color] ?? COLOR_PALETTE["black"]!,
   136	      });
   137	    }
   138	  }
   139	
   140	  return validTypes;
   141	};
   142	
   143	/**
   144	 * Checks whether a specific relation type can connect the given source and
   145	 * target node types (in either direction).
   146	 */
   147	export const isValidRelationConnection = ({
   148	  discourseRelations,
   149	  relationTypeId,
   150	  sourceNodeTypeId,
   151	  targetNodeTypeId,
   152	}: {
   153	  discourseRelations: DiscourseRelation[];
   154	  relationTypeId: string;
   155	  sourceNodeTypeId: string;
   156	  targetNodeTypeId: string;
   157	}): boolean => {
   158	  const { direct, reverse } = getRelationDirection({
   159	    discourseRelations,
   160	    relationTypeId,
   161	    sourceNodeTypeId,
   162	    targetNodeTypeId,
   163	  });
   164	  return direct || reverse;
   165	};
   166	
   167	/**
   168	 * Returns the valid target node type IDs for a given relation type and source
   169	 * node type, checking both forward and reverse directions.
   170	 */
   171	export const getCompatibleTargetNodeTypeIds = ({
   172	  discourseRelations,
   173	  relationTypeId,
   174	  sourceNodeTypeId,
   175	}: {
   176	  discourseRelations: DiscourseRelation[];
   177	  relationTypeId: string;
   178	  sourceNodeTypeId: string;
   179	}): string[] => {
   180	  const targets = new Set<string>();
   181	  for (const relation of discourseRelations) {
   182	    if (relation.relationshipTypeId !== relationTypeId) continue;
   183	    if (relation.sourceId === sourceNodeTypeId)
   184	      targets.add(relation.destinationId);
   185	    if (relation.destinationId === sourceNodeTypeId)
   186	      targets.add(relation.sourceId);
   187	  }
   188	  return [...targets];
   189	};
   190	
   191	/**
   192	 * Checks whether any valid relation type exists between two node types.
   193	 */
   194	export const hasValidRelationTypeForNodePair = ({
   195	  settings,
   196	  sourceNodeTypeId,
   197	  targetNodeTypeId,
   198	}: {
   199	  settings: RelationTypeSettings;
   200	  sourceNodeTypeId: string;
   201	  targetNodeTypeId: string;
   202	}): boolean => {
   203	  return settings.discourseRelations.some(
   204	    (r) =>
   205	      settings.relationTypes.some((rt) => rt.id === r.relationshipTypeId) &&
   206	      ((r.sourceId === sourceNodeTypeId &&
   207	        r.destinationId === targetNodeTypeId) ||
   208	        (r.sourceId === targetNodeTypeId &&
   209	          r.destinationId === sourceNodeTypeId)),
   210	  );
   211	};
