    30	type ResolvedNativeArrowPair = {
    31	  arrow: TLArrowShape;
    32	  startBinding: RelationBinding;
    33	  endBinding: RelationBinding;
    34	  startNode: DiscourseNodeShape;
    35	  endNode: DiscourseNodeShape;
    36	  startNodeTypeId: string;
    37	  endNodeTypeId: string;
    38	};
    39	
    40	type ResolveNativeArrowFailureReason =
    41	  | "not-arrow"
    42	  | "unbound"
    43	  | "same-node"
    44	  | "not-discourse-node"
    45	  | "missing-type-id";
    46	
    47	const isArrowShape = (
    48	  shape: TLShape | null | undefined,
    49	): shape is TLArrowShape => shape?.type === "arrow";
    50	
    51	const getNativeArrowBindings = (
    52	  editor: Editor,
    53	  arrowId: TLShapeId,
    54	): { start?: RelationBinding; end?: RelationBinding } => {
    55	  const bindings = editor.getBindingsFromShape<RelationBinding>(
    56	    arrowId,
    57	    "arrow",
    58	  );
    59	  return {
    60	    start: bindings.find((b) => b.props.terminal === "start"),
    61	    end: bindings.find((b) => b.props.terminal === "end"),
    62	  };
    63	};
    64	
    65	const resolveNativeArrowDiscoursePair = (
    66	  editor: Editor,
    67	  arrowId: TLShapeId,
    68	):
    69	  | { ok: true; value: ResolvedNativeArrowPair }
    70	  | { ok: false; reason: ResolveNativeArrowFailureReason } => {
    71	  const shape = editor.getShape(arrowId);
    72	  if (!isArrowShape(shape)) {
    73	    return { ok: false, reason: "not-arrow" };
    74	  }
    75	
    76	  const { start, end } = getNativeArrowBindings(editor, arrowId);
    77	  if (!start || !end) {
    78	    return { ok: false, reason: "unbound" };
    79	  }
    80	
    81	  if (start.toId === end.toId) {
    82	    return { ok: false, reason: "same-node" };
    83	  }
    84	
    85	  const startNode = editor.getShape(start.toId);
    86	  const endNode = editor.getShape(end.toId);
    87	
    88	  if (
    89	    !startNode ||
    90	    !endNode ||
    91	    !isDiscourseNodeShape(startNode) ||
    92	    !isDiscourseNodeShape(endNode)
    93	  ) {
    94	    return { ok: false, reason: "not-discourse-node" };
    95	  }
    96	
    97	  const startNodeTypeId = getDiscourseNodeTypeId(startNode);
    98	  const endNodeTypeId = getDiscourseNodeTypeId(endNode);
    99	
   100	  if (!startNodeTypeId || !endNodeTypeId) {
   101	    return { ok: false, reason: "missing-type-id" };
   102	  }
   103	
   104	  return {
   105	    ok: true,
   106	    value: {
   107	      arrow: shape,
   108	      startBinding: start,
   109	      endBinding: end,
   110	      startNode,
   111	      endNode,
   112	      startNodeTypeId,
   113	      endNodeTypeId,
   114	    },
   115	  };
   116	};
   117	
   118	const getResolveFailureMessage = (
   119	  reason: ResolveNativeArrowFailureReason,
   120	): string => {
   121	  switch (reason) {
   122	    case "same-node":
   123	      return "Target must be a different discourse node";
   124	    case "unbound":
   125	    case "not-discourse-node":
   126	      return "Arrow must connect two discourse nodes";
   127	    default:
   128	      return "Could not convert this arrow to a relation";
   129	  }
   130	};
   131	
   132	export const getValidRelationTypesForArrow = ({
   133	  editor,
   134	  plugin,
   135	  arrowId,
   136	}: {
   137	  editor: Editor;
   138	  plugin: DiscourseGraphPlugin;
   139	  arrowId: TLShapeId;
   140	}): { id: string; label: string; color: string }[] => {
   141	  const resolved = resolveNativeArrowDiscoursePair(editor, arrowId);
   142	  if (!resolved.ok) return [];
   143	
   144	  return getValidRelationTypesForNodePair({
   145	    settings: plugin.settings,
   146	    sourceNodeTypeId: resolved.value.startNodeTypeId,
   147	    targetNodeTypeId: resolved.value.endNodeTypeId,
   148	  });
   149	};
