  /**
   * Updates the relation text based on the direction of the connection.
   * If the relation is pointing in the reverse direction, shows the complement.
   */
  updateRelationTextForDirection(
    shape: DiscourseRelationShape,
    bindings: RelationBindings,
  ): void {
    const plugin = this.options.plugin;
    const relationTypeId = shape.props.relationTypeId;

    if (!relationTypeId || !bindings.start || !bindings.end) return;

    const startNode = this.editor.getShape(bindings.start.toId);
    const endNode = this.editor.getShape(bindings.end.toId);

    if (!startNode || !endNode) return;

    const startNodeTypeId = getDiscourseNodeTypeId(startNode);
    const endNodeTypeId = getDiscourseNodeTypeId(endNode);

    if (!startNodeTypeId || !endNodeTypeId) return;

    const relationType = getRelationTypeById(plugin, relationTypeId);

    if (!relationType) return;

    const newText = getRelationLabelForDirection({
      discourseRelations: plugin.settings.discourseRelations,
      relationType,
      sourceNodeTypeId: startNodeTypeId,
      targetNodeTypeId: endNodeTypeId,
    });

    // Update the shape text if it's different
    if (shape.props.text !== newText) {
      this.editor.updateShapes([
        {
          id: shape.id,
          type: shape.type,
          props: { text: newText },
        },
      ]);
    }
  }

  /**
   * Reifies the relation in the relations JSON of both connected files.
   * This creates the bidirectional links that make the relation persistent.
   */
  async reifyRelation(
    shape: DiscourseRelationShape,
    bindings: RelationBindings,
  ): Promise<void> {
    if (!bindings.start || !bindings.end || !shape.props.relationTypeId) {
      return;
    }

    const startNode = this.editor.getShape(bindings.start.toId);
    const endNode = this.editor.getShape(bindings.end.toId);

    if (
      !startNode ||
      !endNode ||
      startNode.type !== "discourse-node" ||
      endNode.type !== "discourse-node"
    ) {
      return;
    }

    const persistResult = await persistRelationBetweenNodeShapes({
      plugin: this.options.plugin,
      canvasFile: this.options.canvasFile,
      editor: this.editor,
      startNode: startNode as DiscourseNodeShape,
      endNode: endNode as DiscourseNodeShape,
      relationTypeId: shape.props.relationTypeId,
    });

    if (!persistResult.ok) {
      return;
    }

    if (persistResult.relationInstanceId) {
      this.editor.updateShape({
        id: shape.id,
        type: shape.type,
        meta: {
          ...shape.meta,
          relationInstanceId: persistResult.relationInstanceId,
        },
      });
    }

    const relationType = getRelationTypeById(
      this.options.plugin,
      shape.props.relationTypeId,
    );

    if (relationType && !persistResult.alreadyExisted) {
      showToast({
        severity: "success",
        title: "Relation Created",
        description: `Added ${relationType.label} relation between ${persistResult.sourceFile.basename} and ${persistResult.targetFile.basename}`,
        targetCanvasId: this.options.canvasFile.path,
      });
    }
  }
}

export const createDiscourseRelationUtil = (
  options: DiscourseRelationUtilOptions,
) => {
  const configuredUtil = class extends DiscourseRelationUtil {
    options = options;
  };
  const handleSelect = useCallback(
    (relationId: string) => {
      onSelect(relationId);
    },
    [onSelect],
  );

  if (validRelationTypes.length === 0) return null;

  return (
    <div
      ref={dropdownRef}
      style={{
        position: "absolute",
        left: `${dropdownPos.x}px`,
        top: `${dropdownPos.y}px`,
        transform: "translate(-50%, -50%)",
        pointerEvents: "all",
        zIndex: 30,
      }}
      onPointerDown={(e) => e.stopPropagation()}
      onPointerUp={(e) => e.stopPropagation()}
      onClick={(e) => e.stopPropagation()}
    >
      <div className="max-h-[240px] min-w-[160px] overflow-y-auto rounded-lg border border-gray-200 bg-white p-4 shadow-lg">
        <div className="px-2 py-1 text-xs font-semibold uppercase tracking-wide text-gray-500">
          Relation Type
        </div>
        {validRelationTypes.map((rt) => (
          <button
            key={rt.id}
            onClick={() => handleSelect(rt.id)}
            className="flex w-full cursor-pointer items-center gap-2 rounded-md border-none bg-transparent px-3 py-2 text-left text-[13px] text-[#333] hover:bg-[#f0f0f0]"
            onMouseEnter={(e) => {
              (e.currentTarget as HTMLElement).style.backgroundColor =
                "#f0f0f0";
            }}
            onMouseLeave={(e) => {
              (e.currentTarget as HTMLElement).style.backgroundColor =
                "transparent";
            }}
          >
            <span
              style={{
                backgroundColor: rt.color,
              }}
              className="h-2 w-2 flex-shrink-0 rounded-full bg-[#333]"
            />
            {rt.label}
          </button>
        ))}
      </div>
    </div>
  );
};
